import { parseArgs } from "node:util";
import { TuituiBotClient } from "@qihoo/tuitui-bot-sdk";
import { loadSampleConfig } from "./config.js";

const { values } = parseArgs({
  options: {
    team: { type: "string" },
    channel: { type: "string" },
  },
});

if (!values.team || !values.channel) {
  console.error(
    "用法: npm run sample:send-post -- --team <团队ID> --channel <频道ID>",
  );
  process.exit(1);
}

const config = loadSampleConfig();
const client = new TuituiBotClient(config.appId, config.appSecret);

try {
  const response = await client.teams.sendPost({
    teamId: values.team,
    channelId: values.channel,
    text: "**来自 `@qihoo/tuitui-bot-sdk` 的示例帖子**",
  });

  console.log("频道帖子发送成功", response);
} catch (error) {
  console.error("频道帖子发送失败", error);
}
